import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"ChipValue","description":"","frontmatter":{},"headers":[],"relativePath":"components/chip-value.md","filePath":"components/chip-value.md"}'),r={name:"components/chip-value.md"};function i(h,e,s,n,l,c){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="chipvalue" tabindex="-1">ChipValue <a class="header-anchor" href="#chipvalue" aria-label="Permalink to &quot;ChipValue&quot;">​</a></h1><p>ChipValue is a small surface attached to a point of the stage, which holds a value: an input and the button that confirms it, or the value alone.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it to edit or read one value where it applies on the stage, such as the length of a line being drawn. It is placed absolutely inside the frame that holds the stage (a positioned element), at the point&#39;s distance from the frame&#39;s edges. Collapsed, the chip only reads the value and is itself the trigger that expands it: pass <code>onclick</code> and <code>label</code>. With several values, <code>rows</code> stacks list items. A value edited in a panel is a <a href="./number-input">NumberInput</a> in a <a href="./field">Field</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>top</code></td><td></td><td>The distance from the top: 0, a gap step or a length</td></tr><tr><td><code>right</code></td><td></td><td>The distance from the right</td></tr><tr><td><code>bottom</code></td><td></td><td>The distance from the bottom</td></tr><tr><td><code>left</code></td><td></td><td>The distance from the left</td></tr><tr><td><code>rows</code></td><td><code>false</code></td><td>Stacks list items</td></tr><tr><td><code>onclick</code></td><td></td><td>Makes the chip a button that expands it</td></tr><tr><td><code>label</code></td><td></td><td>The name of that button</td></tr><tr><td><code>children</code></td><td>required</td><td>The input and the button, or the value</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The surface is the panel with a strong line, over the stage (<code>--kata-z-floating</code>). A gap step (<code>2xs</code> to <code>2xl</code>) is that step of the gap scale, and any other string a CSS length. pad-sm inside and gap-sm between its children, which sit in one row and keep their width. It declares the small button for the controls inside, so the author writes no size. As a trigger it shows the raise surface on hover.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/chip-value/" title="ChipValue" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/chip-value/" target="_blank" rel="noopener">ChipValue</a></figcaption></figure>',10)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
